    "room.202.chat.42.text": "[Sigue trabajando]",
    "room.202.chat.42.choice.0": "...",
    "room.202.chat.43.text": "Mírate: eres un desastre lamentable, lleno de babas. ¿Ya quieres parar?",
    "room.202.chat.43.choice.0": "AaaaAAAA uuuUUhhhhh",
