    "room.24.chat.32.choice.0": "...",
    "room.23.chat.0.text": "¡Qué ganas tengo! Nunca he jugado a «Verdad o reto», pero he oído hablar mucho del juego. Espero que no nos hagas hacer nada pervertido... *guiño*",
    "room.23.chat.0.choice.0": "...",
    "room.23.chat.1.text": { "text": "Lo que tú digas, {lola}. Sabes que tu lado más guarro quiere que {me} se comporte como un pervertido total.", "values": ["lola", "me"] },
    "room.23.chat.1.choice.0": { "text": "No te preocupes, {eva}. Me aseguraré de que tú también participes.", "values": ["eva"] },
    "room.23.chat.2.text": "Jajaja, ¡más te vale, rarito!",
