    "room.23.chat.28.choice.0": "...",
    "room.23.chat.29.text": "¡Ufff! Qué mareo.",
    "room.23.chat.29.choice.0": "...",
    "room.23.chat.30.text": "Jejeje, ¿qué te parece?",
    "room.23.chat.30.choice.0": "¡Impresionante!",
