    "room.23.chat.32.text": { "text": "{eva}, ¿verdad o reto?", "values": ["eva"] },
    "room.23.chat.32.choice.0": "...",
    "room.23.chat.33.text": "¡Atrévete!",
    "room.23.chat.33.choice.0": "...",
    "room.23.chat.34.text": "¡Te reto a que también te quedes en topless! ¡No voy a ser la única enseñando las tetas!",
    "room.23.chat.34.choice.0": "...",
    "room.23.chat.37.text": "¡Quítate la parte de arriba! ¡Enséñanos esas tetas!",
    "room.23.chat.37.choice.0": "...",
    "room.23.chat.38.text": "¡Vale! Como yo propuse el juego, empezaré yo.",
