    "room.23.chat.66.text": { "text": "Siempre hacemos todo juntas, así que no pienso quedarme aquí desnuda yo sola. ¡{eva}, tú también tienes que desnudarte!", "values": ["eva"] },
    "room.23.chat.66.choice.0": "...",
