    "room.23.chat.104.choice.0": { "text": "No me rindo. {lola}, dame unas bragas tuyas.", "values": ["lola"] },
    "room.23.chat.104.choice.1": "No pienso hacerlo. Ya basta por esta noche.",
    "room.23.chat.105.text": "Más te vale no manchar mis bragas con tus cosas asquerosas.",
    "room.23.chat.105.choice.0": "Si pasa, pasa. Intenta no estar tan sexy.",
    "room.23.chat.106.text": "Jejeje. Culo.",
    "room.23.chat.106.choice.0": "Tienes los dedos fríos.",
    "room.23.chat.107.text": "¿Por qué a los pervertidos perdedores siempre les tocan pollas tan grandes?",
    "room.23.chat.107.choice.0": "¡Eh!",
    "room.23.chat.108.text": { "text": "{landlord} me prometió un cachorro, pero cambió de opinión como siempre, después de que ya hubiera comprado un montón de cosas para mi perrito. ¡Ahora cómetelo, chico-perro!", "values": ["landlord"] },
    "room.23.chat.108.choice.0": "Grrmf.",
