    "room.23.chat.116.choice.0": "...",
    "room.23.chat.117.text": { "text": "{me}, ¿verdad o reto?", "values": ["me"] },
    "room.23.chat.117.choice.0": "Reto",
    "room.23.chat.117.choice.1": "Verdad",
    "room.23.chat.118.text": "Gallina. Nosotras ya nos hemos desnudado y tú eliges verdad. Elige reto.",
    "room.23.chat.118.choice.0": "Vale. Atrévete.",
